const body = $input.first().json.body ?? $input.first().json;
if (!body.doc_type) { throw new Error('doc_type es requerido'); }
if (!body.file_url && !body.file_base64) { throw new Error('file_url o file_base64 es requerido'); }
return [{ json: { doc_type: body.doc_type, file_url: body.file_url ?? null, file_base64: body.file_base64 ?? null, source: body.source ?? 'manual' } }];

const err = $input.first().json;
const detalle = err.error?.message ?? err.message ?? JSON.stringify(err);
return [{ json: { text: `🔴 <b>OCR: fallo al procesar documento</b>\nDetalle: <code>${detalle}</code>` } }];

// Mapea la salida cruda del OCR al contrato normalizado (mejora #23).
// Sin fallback cloud: bajo el umbral, el documento se marca requires_review
// y se resuelve via revision humana (mejora #29), no via una segunda API.
const raw = $input.first().json;
const CONFIDENCE_THRESHOLD = 80;
const requiresReview = (raw.confidence_global ?? 0) < CONFIDENCE_THRESHOLD;

// Normaliza RFC: sin espacios/guiones, mayusculas.
const vatRaw = raw.fields?.vendor_vat ?? '';
const vatNormalized = vatRaw.replace(/[\s-]/g, '').toUpperCase();

// Mejora #24 (match difuso): O/0 e I/1 son la confusion OCR mas comun en RFCs.
// Genera variantes candidatas ademas de la lectura literal, para no mandar
// a revision manual por un solo caracter ambiguo cuando el resto es correcto.
function fuzzyVariants(rfc) {
  const variants = new Set([rfc]);
  for (let i = 0; i < rfc.length; i++) {
    const c = rfc[i];
    const swaps = { 'O': '0', '0': 'O', 'I': '1', '1': 'I' };
    if (swaps[c]) {
      variants.add(rfc.slice(0, i) + swaps[c] + rfc.slice(i + 1));
    }
  }
  return Array.from(variants);
}
const vatCandidates = vatNormalized ? fuzzyVariants(vatNormalized) : [];

// Convierte fecha dd/mm/yyyy -> yyyy-mm-dd para Odoo. Si no matchea, usa hoy.
let invoiceDate = null;
const dateMatch = (raw.fields?.date ?? '').match(/(\d{1,2})[/-](\d{1,2})[/-](\d{2,4})/);
if (dateMatch) {
  const [, d, m, y] = dateMatch;
  const year = y.length === 2 ? `20${y}` : y;
  invoiceDate = `${year}-${m.padStart(2,'0')}-${d.padStart(2,'0')}`;
}

return [{ json: {
  invoice_number: raw.fields?.invoice_number ?? null,
  vendor_vat: vatNormalized || null,
  vendor_vat_candidates: vatCandidates,
  invoice_date: invoiceDate,
  lines: raw.fields?.lines ?? [],
  confidence_global: raw.confidence_global ?? 0,
  requires_review: requiresReview
} }];

const norm = $('Normalizar Campos Extraidos').first().json;
return [{ json: { text: `🟡 <b>OCR: proveedor no encontrado en Odoo</b>
RFC detectado: <code>${norm.vendor_vat ?? 'N/D'}</code>
Factura: ${norm.invoice_number ?? 'N/D'}

Requiere alta manual del proveedor o revision del RFC extraido.` } }];

const err = $input.first().json;
const detalle = err.error?.message ?? err.message ?? JSON.stringify(err);
return [{ json: { text: `🔴 <b>OCR: fallo al autenticar contra Odoo</b>\nDetalle: <code>${detalle}</code>` } }];

const norm = $('Normalizar Campos Extraidos').first().json;
const partner = $('Buscar Partner en Odoo').first().json.result[0];
const moveId = $('Crear Factura Borrador en Odoo').first().json.result;
return [{ json: {
  requires_review: norm.requires_review,
  move_id: moveId,
  text: `📄 <b>OCR procesado</b>\nProveedor: ${partner.name}\nFactura: ${norm.invoice_number ?? 'N/D'}\nConfianza: ${norm.confidence_global}%\nRevisión requerida: ${norm.requires_review ? 'Sí' : 'No'}\nOdoo: account.move #${moveId} (borrador)`
} }];

function safeGet(nodeName, field) {
  try { return $(nodeName).first().json[field]; } catch (e) { return undefined; }
}
const moveId = safeGet('Formatear Exito OCR', 'move_id');
const requiresReview = safeGet('Formatear Exito OCR', 'requires_review');
const isManualReview = safeGet('Preparar Alerta - Revision Manual', 'text') !== undefined;
const isFailure = safeGet('Preparar Alerta - Fallo OCR', 'text') !== undefined || safeGet('Preparar Alerta - Fallo Autenticacion', 'text') !== undefined;
return [{ json: {
  ok: !isFailure,
  move_id: moveId ?? null,
  requires_review: isManualReview ? true : (requiresReview ?? null)
} }];
